import{_ as a,o as s,c as n,a6 as i}from"./chunks/framework.DL_pga9_.js";const h=JSON.parse('{"title":"Tuple Design","description":"","frontmatter":{},"headers":[],"relativePath":"design/archive/tuples.md","filePath":"design/archive/tuples.md","lastUpdated":1780030916000}'),t={name:"design/archive/tuples.md"};function l(p,e,r,c,o,d){return s(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="tuple-design" tabindex="-1">Tuple Design <a class="header-anchor" href="#tuple-design" aria-label="Permalink to “Tuple Design”">​</a></h1><p>Original discussion: <a href="https://github.com/ng-lang/ng/discussions/21" target="_blank" rel="noreferrer">https://github.com/ng-lang/ng/discussions/21</a></p><p>This document records the current tuple design after the StorageCell runtime, ORGASM compiler, and enhanced generics work. It supersedes the older staged checklist in the discussion body while keeping the same motivation: tuples are heterogeneous positional product values used for multiple returns, multiple bindings, spread/unpack, and variadic generic packs.</p><h2 id="current-semantics" tabindex="-1">Current Semantics <a class="header-anchor" href="#current-semantics" aria-label="Permalink to “Current Semantics”">​</a></h2><p>A tuple is a value with fixed arity and per-slot element types.</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>val x = (1, &quot;a&quot;, false);</span></span>
<span class="line"><span>val y: (i32, string, bool) = x;</span></span>
<span class="line"><span>val (a, b, c) = y;</span></span></code></pre></div><p>Runtime representation:</p><ul><li>Tuples are StorageCell-backed runtime values with slot-backed elements.</li><li>Tuple elements are addressed by zero-based numeric members and indexes.</li><li>Tuple values support copying, equality, display, GC tracing, and slot mutation through the same runtime value access layer as arrays and structural objects.</li><li><code>unit</code> remains the unit value/type. It is not treated as a zero-length tuple.</li></ul><p>Supported value operations:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>val tup = (1, false, &quot;hello&quot;);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>assert(tup.size == 3);</span></span>
<span class="line"><span>assert(tup.0 == 1);</span></span>
<span class="line"><span>assert(tup[1] == false);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>tup.1 := true;</span></span>
<span class="line"><span>assert(tup[1] == true);</span></span></code></pre></div><p>Supported unpacking and spread construction:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>val x = (1, false, &quot;hello&quot;);</span></span>
<span class="line"><span>val y = (0, ...x, 4);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>val (head, ...tail) = y;</span></span>
<span class="line"><span>assert(head == 0);</span></span>
<span class="line"><span>assert(tail.size == 4);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>val arr = [1, 2, 3];</span></span>
<span class="line"><span>val [first, ...rest] = arr;</span></span>
<span class="line"><span>val arr2 = [0, ...arr, 4];</span></span></code></pre></div><p>Supported variadic generic packs:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fun count&lt;T...&gt;(args: T...) -&gt; u32 {</span></span>
<span class="line"><span>  return args.size;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>assert(count(1, &quot;two&quot;, true) == 3);</span></span></code></pre></div><p>Pack parameters are materialized as tuple-like varargs values in type checking and as runtime tuples when invoked. <code>next ...tail</code> is supported for recursive pack processing.</p><h2 id="discussion-21-status" tabindex="-1">Discussion #21 Status <a class="header-anchor" href="#discussion-21-status" aria-label="Permalink to “Discussion #21 Status”">​</a></h2><p>The linked discussion proposed four broad areas. Their current status is:</p><ul><li>Tuple literals and tuple type annotations are implemented.</li><li>Tuple <code>.size</code>, numeric member access, index access, and element assignment are implemented for runtime values.</li><li>Tuple and array spread construction are implemented.</li><li>Tuple and array destructuring with optional trailing rest binding are implemented.</li><li>Multiple returns are represented as returning tuple values.</li><li>Generic parameter packs are implemented and cover the main variadic function use case better than the original native-only variadic proposal.</li><li>Prelude <code>print</code> and <code>assert</code> are backed by variadic native handling; user-defined <code>fun&lt;T...&gt;(args: T...)</code> is supported.</li><li>Range expressions (<code>a..b</code>, <code>a..=b</code>), from-end indexing (<code>^n</code>), and slice syntax are implemented. The old <code>range(...)</code> and <code>slice(...)</code> helper APIs have been removed.</li><li>Tuple type-level operations such as <code>&lt;tuple&gt;.size</code> as a compile-time type expression and <code>&lt;tuple&gt;[N]</code> as an element type projection are not implemented.</li><li>Fold/map/filter postfix syntax and pipeline syntax from the discussion are not implemented.</li></ul><h2 id="covered-by-enhanced-generics" tabindex="-1">Covered By Enhanced Generics <a class="header-anchor" href="#covered-by-enhanced-generics" aria-label="Permalink to “Covered By Enhanced Generics”">​</a></h2><p>Enhanced generics already cover several capabilities that the original tuple proposal expected from &quot;enhanced tuple type support&quot;:</p><ul><li>Heterogeneous variadic arguments are modeled with generic packs: <code>T...</code>.</li><li>Pack parameters are type checked as <code>VarargsType</code> and can be destructured like tuples.</li><li>Type specialization and const predicates can select behavior based on reified generic types.</li><li>Variadic higher-kinded generic parameters can describe constructors with a variable type tail, e.g. <code>F&lt;_, ...&gt;</code>.</li><li>ORGASM compilation monomorphizes generic instances instead of carrying unresolved generic tuple metadata at runtime.</li></ul><p>These features reduce the need for tuple-specific metaprogramming in ordinary APIs. For example, a function that once needed <code>typeof(args).size</code> can usually be written as a pack function whose body uses <code>args.size</code> at value level.</p><p>Enhanced generics do not replace tuple type introspection. APIs that need compile-time arity, element type projection, tuple concatenation at type level, or function signatures derived from tuple types still need explicit enhanced tuple rules.</p><h2 id="remaining-gaps" tabindex="-1">Remaining Gaps <a class="header-anchor" href="#remaining-gaps" aria-label="Permalink to “Remaining Gaps”">​</a></h2><p>The remaining work should be split from the original broad tuple discussion into smaller designs:</p><ul><li>Enhanced tuple types: compile-time tuple arity, element projection, pack-to-tuple normalization, tuple concatenation, and function type interop.</li><li>Range operators: <code>a..b</code>, <code>a..=b</code>, open ranges, and from-end indexes; see <a href="./../ranges_slicing_pipeline">ranges_slicing_pipeline.md</a>.</li><li>Tuple and array slicing syntax: <code>xs[a..b]</code>, <code>xs[^n]</code>, and tuple slice type preservation; see <a href="./../enhanced_tuples">enhanced_tuples.md</a> for tuple type rules.</li><li>General function application via spread: make <code>f(...tuple)</code> consistently type checked and compiled for non-pack functions, default parameters, and trait/object method calls.</li><li>Fold/pipeline syntax: should be redesigned separately over traits or prelude functions instead of overloading tuple spread semantics further.</li></ul><p>The follow-up enhanced tuple plan is in <a href="./../enhanced_tuples">enhanced_tuples.md</a>.</p><h2 id="acceptance-baseline" tabindex="-1">Acceptance Baseline <a class="header-anchor" href="#acceptance-baseline" aria-label="Permalink to “Acceptance Baseline”">​</a></h2><p>The current implementation is expected to keep these examples working in both STUPID and ORGASM unless explicitly noted by tests:</p><ul><li><code>example/14.tuple.ng</code></li><li>Generic packs in <code>example/15.generics.ng</code></li><li>Tuple spread and rest binding in <code>test/typecheck/typecheck_tuple_test.cpp</code></li><li>Runtime tuple layout and indexed access tests in <code>test/runtime/runtime_value_ops_test.cpp</code></li><li>ORGASM tuple example coverage in <code>test/orgasm/examples_test.cpp</code></li></ul><p>Any future tuple work should extend this baseline rather than introduce a separate tuple runtime path.</p>`,31)])])}const g=a(t,[["render",l]]);export{h as __pageData,g as default};
